function reducer(state, action) {
  switch (action.type) {
    case 'NAVIGATE':
      return { ...state, activeScreen: action.payload };
    case 'SELECT_GAP':
      return { ...state, uiState: { ...state.uiState, selectedGapId: action.payload }, activeScreen: 'gap_detail' };
    case 'ASSIGN_RECOMMENDATION':
      return {
        ...state,
        gaps: state.gaps.map(g => g.id === action.payload.gapId ? { ...g, status: 'Accepted' } : g),
        uiState: { ...state.uiState, toast: `Assigned to ${action.payload.owner}` }
      };
    case 'RESOLVE_KPI':
      return {
        ...state,
        kpis: state.kpis.map(k => k.id === action.payload ? { ...k, conflict_state: 'Reconciled' } : k),
        uiState: { ...state.uiState, toast: 'Canonical KPI published to all dashboards' }
      };
    case 'CLEAR_TOAST':
      return { ...state, uiState: { ...state.uiState, toast: null } };
    default:
      return state;
  }
}

