const NuButton = ({ variant = 'primary', children, onClick, disabled }) => {
  const baseStyle = { padding: '8px 16px', borderRadius: '4px', cursor: disabled ? 'not-allowed' : 'pointer', fontWeight: 500, fontSize: '13px', border: 'none', transition: 'all 0.2s' };
  const variants = {
    primary: { backgroundColor: 'var(--nu-accent)', color: 'var(--nu-paper)' },
    secondary: { backgroundColor: 'var(--nu-paper)', color: 'var(--nu-ink)', border: '1px solid var(--nu-hairline)' },
    tertiary: { backgroundColor: 'transparent', color: 'var(--nu-ink)' }
  };
  return (
    <button style={{ ...baseStyle, ...variants[variant], opacity: disabled ? 0.5 : 1 }} onClick={onClick} disabled={disabled}>
      {children}
    </button>
  );
};

const NuBadge = ({ variant = 'neutral', children }) => {
  const variants = {
    neutral: { bg: 'var(--nu-ecru)', color: 'var(--nu-ink)' },
    success: { bg: '#EDF7F5', color: 'var(--nu-success)' },
    warning: { bg: '#FFF8E1', color: 'var(--nu-warning)' },
    danger: { bg: '#FAEDED', color: 'var(--nu-friction)' }
  };
  const style = variants[variant] || variants.neutral;
  return (
    <span style={{ backgroundColor: style.bg, color: style.color, padding: '4px 12px', borderRadius: '999px', fontSize: '11.5px', fontWeight: 500, display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
      {children}
    </span>
  );
};

const NuCard = ({ children, onClick, style = {} }) => (
  <div 
    onClick={onClick}
    style={{ 
      backgroundColor: 'var(--nu-paper)', 
      border: '1px solid var(--nu-hairline)', 
      borderRadius: '8px', 
      padding: '32px 30px', 
      cursor: onClick ? 'pointer' : 'default',
      transition: 'box-shadow 0.2s, transform 0.2s',
      ...style 
    }}
    onMouseEnter={(e) => onClick && (e.currentTarget.style.boxShadow = '0 4px 12px rgba(11,19,38,0.08)', e.currentTarget.style.transform = 'translateY(-2px)')}
    onMouseLeave={(e) => onClick && (e.currentTarget.style.boxShadow = 'none', e.currentTarget.style.transform = 'none')}
  >
    {children}
  </div>
);

