function Screen_scorecard_home({ state, dispatch }) {
  const { metrics, gaps } = state;
  const { TrendingUp, TrendingDown, ArrowRight, AlertTriangle, Activity } = window.lucide;

  const pillars = [
    { key: 'alignment_score', label: 'Alignment', value: metrics.alignment_score, delta: +3, dir: 'up' },
    { key: 'integration_score', label: 'Integration', value: metrics.integration_score, delta: -2, dir: 'down' },
    { key: 'kpi_score', label: 'Shared KPIs', value: metrics.kpi_score, delta: +5, dir: 'up' }
  ];

  const pillarColor = (v) => v >= 70 ? 'var(--nu-success)' : v >= 60 ? 'var(--nu-warning)' : 'var(--nu-friction)';

  const Gauge = ({ value, color }) => {
    const r = 52, c = 2 * Math.PI * r;
    const pct = Math.max(0, Math.min(100, value)) / 100;
    return (
      <svg viewBox="0 0 130 130" width="130" height="130" aria-hidden="true">
        <circle cx="65" cy="65" r={r} fill="none" stroke="var(--nu-hairline)" strokeWidth="10" />
        <circle
          cx="65" cy="65" r={r} fill="none" stroke={color} strokeWidth="10" strokeLinecap="round"
          strokeDasharray={c} strokeDashoffset={c * (1 - pct)}
          transform="rotate(-90 65 65)"
        />
        <text x="65" y="62" textAnchor="middle" className="nu-data" fill="var(--nu-ink)" style={{ fontSize: '32px' }}>{value}</text>
        <text x="65" y="84" textAnchor="middle" fill="var(--nu-grey)" style={{ fontSize: '11px', fontWeight: 500 }}>/ 100</text>
      </svg>
    );
  };

  const pillarOf = (g) => g.pillar === 'Integration' ? 'danger' : g.pillar === 'Alignment' ? 'warning' : 'neutral';

  return (
    <div className="flex-col" style={{ gap: '32px' }}>
      {/* Weekly change digest banner */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '16px', backgroundColor: 'var(--nu-ink)', color: 'var(--nu-paper)', borderRadius: '8px', padding: '20px 28px' }}>
        <Activity size={22} color="var(--nu-paper)" strokeWidth={2} />
        <div style={{ flex: 1 }}>
          <div className="nu-kicker" style={{ color: 'var(--nu-paper)', opacity: 0.7, marginBottom: '4px' }}>This Week's Movement</div>
          <div style={{ fontSize: '15px', fontWeight: 500, lineHeight: 1.4 }}>
            Composite readiness up <strong>+2 pts</strong> to {metrics.composite_score}. Integration slipped 2 pts after the EventsPlatform sync break. 1 new gap detected, 1 recommendation moved to In-Progress.
          </div>
        </div>
      </div>

      {/* p-kpi: pillar gauges + composite */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '24px' }}>
        {pillars.map(p => (
          <NuCard key={p.key} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px' }}>
            <span className="nu-label" style={{ letterSpacing: '1.5px' }}>{p.label}</span>
            <Gauge value={p.value} color={pillarColor(p.value)} />
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: p.dir === 'up' ? 'var(--nu-success)' : 'var(--nu-friction)', fontWeight: 600, fontSize: '13px' }}>
              {p.dir === 'up' ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
              {p.dir === 'up' ? '+' : ''}{p.delta} this week
            </div>
          </NuCard>
        ))}

        {/* Composite */}
        <NuCard style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px', backgroundColor: 'var(--nu-rail)', border: 'none' }}>
          <span className="nu-label" style={{ color: 'var(--nu-paper)', opacity: 0.65, letterSpacing: '1.5px' }}>Composite Readiness</span>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '130px' }}>
            <span className="nu-title" style={{ color: 'var(--nu-paper)', fontSize: '64px' }}>{metrics.composite_score}</span>
            <span style={{ color: 'var(--nu-paper)', opacity: 0.5, fontSize: '12px', fontWeight: 500, marginTop: '4px' }}>2026 CAMPAIGN READY AT 80</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: 'var(--nu-success)', fontWeight: 600, fontSize: '13px' }}>
            <TrendingUp size={16} /> +2 this week
          </div>
        </NuCard>
      </div>

      {/* Top changed gaps — entry point to triage */}
      <div>
        <div className="flex items-center justify-between" style={{ marginBottom: '18px' }}>
          <div>
            <h2 className="nu-subhead" style={{ fontSize: '26px' }}>Top Priority Gaps</h2>
            <p className="nu-label" style={{ marginTop: '4px' }}>Highest severity of 28 detected · click to triage</p>
          </div>
          <NuButton variant="secondary" onClick={() => dispatch({ type: 'NAVIGATE', payload: 'roadmap_board' })}>
            View all on roadmap
          </NuButton>
        </div>

        <div className="flex-col" style={{ gap: '16px' }}>
          {gaps.slice(0, 3).map(g => (
            <NuCard key={g.id} onClick={() => dispatch({ type: 'SELECT_GAP', payload: g.id })} style={{ padding: '24px 28px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '28px' }}>
                {/* severity number */}
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', minWidth: '64px' }}>
