                  <span className="nu-label" style={{ letterSpacing: '1px', fontSize: '11px' }}>SEVERITY</span>
                </div>

                {/* title + bar */}
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '10px' }}>
                    <NuBadge variant={pillarOf(g)}>{g.pillar}</NuBadge>
                    <span style={{ fontSize: '12px', color: 'var(--nu-grey)' }}>{g.id} · {g.affected_records.toLocaleString()} records</span>
