                  <div style={{ fontSize: '18px', fontWeight: 700, color: 'var(--nu-ink)', marginBottom: '12px' }}>{g.title}</div>
                  <div style={{ height: '8px', borderRadius: '999px', backgroundColor: 'var(--nu-ecru)', overflow: 'hidden' }}>
                    <div style={{ width: `${g.severity}%`, height: '100%', borderRadius: '999px', backgroundColor: g.severity >= 85 ? 'var(--nu-friction)' : g.severity >= 70 ? 'var(--nu-warning)' : 'var(--nu-success)' }} />
                  </div>
                </div>

                {/* dollar at risk */}
                <div style={{ textAlign: 'right', minWidth: '150px' }}>
                  <div className="nu-data" style={{ fontSize: '30px', color: 'var(--nu-ink)' }}>
                    ${(g.dollar_at_risk / 1000000).toFixed(g.dollar_at_risk >= 1000000 ? 1 : 2)}M
                  </div>
                  <span className="nu-label" style={{ letterSpacing: '1px', fontSize: '11px' }}>EST. AT RISK</span>
                </div>

                <ArrowRight size={22} color="var(--nu-grey)" />
              </div>
            </NuCard>
          ))}
        </div>
      </div>
    </div>
  );
}

