function Screen_gap_detail({ state, dispatch }) {
  const gap = state.gaps.find(g => g.id === state.uiState.selectedGapId) || state.gaps[0];
  const rec = state.recommendations.find(r => r.gap_id === gap.id);
  const lucide = window.lucide;

  const [animatedDollar, setAnimatedDollar] = React.useState(0);

  React.useEffect(() => {
    let raf;
    const start = performance.now();
    const duration = 900;
    const target = gap.dollar_at_risk;
    const tick = (now) => {
      const t = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      setAnimatedDollar(Math.round(target * eased));
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [gap.id, gap.dollar_at_risk]);

  const severityColor = gap.severity >= 85 ? 'var(--nu-friction)' : gap.severity >= 70 ? 'var(--nu-warning)' : 'var(--nu-success)';
  const statusVariant = gap.status === 'Accepted' ? 'success' : gap.status === 'In-Progress' ? 'warning' : 'neutral';

  const fmtDollar = (n) => '$' + n.toLocaleString('en-US');

  const handleAssign = () => {
    if (!rec) return;
    dispatch({ type: 'ASSIGN_RECOMMENDATION', payload: { gapId: gap.id, owner: rec.owner } });
  };

  return (
    <div className="flex-col gap-8">
      {/* Back + title */}
      <div className="flex-col" style={{ gap: '12px' }}>
        <NuButton variant="tertiary" onClick={() => dispatch({ type: 'NAVIGATE', payload: 'scorecard_home' })}>
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
            <lucide.ArrowLeft size={15} strokeWidth={2} /> Back to Scorecard
          </span>
        </NuButton>
        <div className="flex items-center gap-4" style={{ flexWrap: 'wrap' }}>
          <span className="nu-kicker">{gap.id} · {gap.pillar}</span>
          <NuBadge variant={statusVariant}>{gap.status}</NuBadge>
        </div>
        <h2 className="nu-subhead" style={{ margin: 0 }}>{gap.title}</h2>
      </div>

      {/* Severity / dollar strip */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '24px' }}>
        <NuCard>
          <div className="nu-label" style={{ marginBottom: '14px' }}>Severity Index</div>
          <div className="flex items-center gap-4">
            <span className="nu-data" style={{ color: severityColor }}>{gap.severity}</span>
            <span className="nu-body" style={{ color: 'var(--nu-grey)' }}>/ 100</span>
          </div>
          <div style={{ marginTop: '16px', height: '8px', borderRadius: '999px', backgroundColor: 'var(--nu-ecru)', overflow: 'hidden' }}>
            <div style={{ width: `${gap.severity}%`, height: '100%', backgroundColor: severityColor, borderRadius: '999px', transition: 'width 0.6s' }} />
          </div>
        </NuCard>

        {/* p-synth dollar */}
        <NuCard>
          <div className="nu-label" style={{ marginBottom: '14px' }}>Dollar at Risk</div>
          <span className="nu-data" style={{ color: 'var(--nu-friction)', fontVariantNumeric: 'tabular-nums' }}>
            {fmtDollar(animatedDollar)}
