          <div className="flex items-center gap-4" style={{ marginTop: '16px', color: 'var(--nu-grey)' }}>
            <lucide.AlertTriangle size={15} strokeWidth={2} />
            <span style={{ fontSize: '13px' }}>Annualized exposure if unresolved</span>
          </div>
        </NuCard>

        <NuCard>
          <div className="nu-label" style={{ marginBottom: '14px' }}>Affected Records</div>
          <span className="nu-data">{gap.affected_records.toLocaleString('en-US')}</span>
          <div className="flex items-center gap-4" style={{ marginTop: '16px', color: 'var(--nu-grey)' }}>
            <lucide.Database size={15} strokeWidth={2} />
            <span style={{ fontSize: '13px' }}>Detected {gap.detected_date}</span>
          </div>
        </NuCard>
      </div>

      {/* p-info-flow Sankey */}
      <NuCard>
        <div className="nu-label" style={{ marginBottom: '6px' }}>Record Flow</div>
        <p className="nu-body" style={{ margin: '0 0 28px', fontSize: '15px', color: 'var(--nu-grey)' }}>
          Where {gap.affected_records.toLocaleString('en-US')} records degrade across the {gap.source_teams.join(' → ')} handoff.
        </p>
        <div className="flex items-center" style={{ gap: '0' }}>
          {gap.source_teams.map((team, i) => (
            <React.Fragment key={team}>
              <div style={{
                flex: '0 0 220px',
                backgroundColor: 'var(--nu-ecru)',
                border: '1px solid var(--nu-hairline)',
                borderRadius: '8px',
                padding: '18px 20px'
              }}>
                <div className="flex items-center gap-4" style={{ marginBottom: '10px' }}>
                  <lucide.Building2 size={18} strokeWidth={2} color="var(--nu-grey)" />
                  <span style={{ fontWeight: 700, fontSize: '15px' }}>{team}</span>
                </div>
                <div style={{ fontSize: '12.5px', color: 'var(--nu-grey)' }}>
                  {i === 0 ? 'Source system' : 'Destination system'}
                </div>
              </div>
              {i < gap.source_teams.length - 1 && (
                <div style={{ flex: 1, position: 'relative', height: '64px' }}>
                  <svg width="100%" height="64" viewBox="0 0 200 64" preserveAspectRatio="none" style={{ display: 'block' }}>
                    <defs>
                      <linearGradient id="flowGrad" x1="0" y1="0" x2="1" y2="0">
                        <stop offset="0%" stopColor="var(--nu-source)" stopOpacity="0.35" />
                        <stop offset="100%" stopColor="var(--nu-friction)" stopOpacity="0.5" />
                      </linearGradient>
                    </defs>
                    <path d="M0,12 C70,12 130,52 200,52 L200,60 C130,20 70,20 0,20 Z" fill="url(#flowGrad)" />
                  </svg>
                  <div style={{
                    position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)',
                    backgroundColor: 'var(--nu-paper)', border: '1px solid var(--nu-hairline)', borderRadius: '999px',
                    padding: '3px 12px', fontSize: '11.5px', color: 'var(--nu-friction)', fontWeight: 500,
                    whiteSpace: 'nowrap'
                  }}>
                    integrity loss
                  </div>
                </div>
              )}
            </React.Fragment>
          ))}
        </div>
      </NuCard>

      {/* p-synth root cause */}
      <NuCard style={{ backgroundColor: 'var(--nu-ink)', color: 'var(--nu-paper)', border: 'none' }}>
        <div className="flex items-center gap-4" style={{ marginBottom: '16px' }}>
          <lucide.Sparkles size={18} strokeWidth={2} color="var(--nu-accent)" />
          <span className="nu-kicker" style={{ color: 'var(--nu-accent)' }}>AI-Attributed Root Cause</span>
        </div>
        <p className="nu-body" style={{ margin: 0, color: 'var(--nu-paper)' }}>{gap.root_cause}</p>
        <div className="flex items-center gap-4" style={{ marginTop: '20px', fontSize: '12.5px', color: 'rgba(255,255,255,0.6)' }}>
          <lucide.GitBranch size={14} strokeWidth={2} />
          <span>Recommended workstream: {gap.recommended_workstream}</span>
        </div>
      </NuCard>

      {/* p-rec recommendation */}
      {rec && (
        <NuCard>
          <div className="flex justify-between items-center" style={{ marginBottom: '20px' }}>
            <span className="nu-kicker">Recommended Fix · {rec.id}</span>
            <NuBadge variant={rec.status === 'Accepted' ? 'success' : rec.status === 'In-Progress' ? 'warning' : 'neutral'}>{rec.status}</NuBadge>
          </div>
          <h3 className="nu-subhead" style={{ fontSize: '24px', margin: '0 0 20px' }}>{rec.title}</h3>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '28px' }}>
            {[
              { label: 'Impact', value: rec.impact_score, icon: 'TrendingUp' },
              { label: 'Effort', value: rec.effort_score, icon: 'Gauge' },
            ].map(m => {
              const Ic = lucide[m.icon];
              return (
                <div key={m.label}>
                  <div className="flex items-center gap-4" style={{ color: 'var(--nu-grey)', marginBottom: '8px' }}>
                    <Ic size={14} strokeWidth={2} />
                    <span className="nu-label" style={{ letterSpacing: '1px' }}>{m.label}</span>
                  </div>
                  <span style={{ fontSize: '28px', fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>{m.value}</span>
                </div>
              );
            })}
            <div>
              <div className="flex items-center gap-4" style={{ color: 'var(--nu-grey)', marginBottom: '8px' }}>
                <lucide.User size={14} strokeWidth={2} />
                <span className="nu-label" style={{ letterSpacing: '1px' }}>Owner</span>
              </div>
              <span style={{ fontSize: '15px', fontWeight: 500 }}>{rec.owner}</span>
            </div>
            <div>
              <div className="flex items-center gap-4" style={{ color: 'var(--nu-grey)', marginBottom: '8px' }}>
                <lucide.Flag size={14} strokeWidth={2} />
                <span className="nu-label" style={{ letterSpacing: '1px' }}>Phase</span>
              </div>
              <span style={{ fontSize: '15px', fontWeight: 500 }}>{rec.phase}</span>
            </div>
          </div>

          <div className="flex items-center justify-between" style={{ borderTop: '1px solid var(--nu-hairline)', paddingTop: '20px' }}>
            <span style={{ fontSize: '13px', color: 'var(--nu-grey)' }}>
              Velocity: <strong style={{ color: 'var(--nu-ink)' }}>{rec.velocity}</strong> · Updated {rec.last_update}
            </span>
            <div className="flex gap-4">
              <NuButton variant="secondary" onClick={() => dispatch({ type: 'NAVIGATE', payload: 'roadmap_board' })}>
                View on Roadmap
              </NuButton>
              <NuButton
                variant="primary"
                disabled={gap.status === 'Accepted'}
                onClick={handleAssign}
              >
                <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
                  <lucide.CheckCircle size={14} strokeWidth={2} />
                  {gap.status === 'Accepted' ? `Assigned to ${rec.owner}` : `Assign to ${rec.owner}`}
                </span>
              </NuButton>
            </div>
          </div>
        </NuCard>
      )}
    </div>
  );
}

// PATTERN MANIFEST: p-compare, p-hitl
function Screen_kpi_builder({ state, dispatch }) {
  const { AlertOctagon, CheckCircle2, GitMerge, Sparkles, ArrowRight, Users, Target } = window.lucide;
  const [reviewing, setReviewing] = React.useState(null);

  const fmtValue = (kpi) =>
    kpi.unit === '%' ? `${kpi.current_value}%` : kpi.current_value.toLocaleString();
  const fmtTarget = (kpi) =>
    kpi.unit === '%' ? `${kpi.target_value}%` : kpi.target_value.toLocaleString();

  return (
    <div className="flex-col gap-8">
      <div className="flex justify-between items-center" style={{ marginBottom: '8px' }}>
        <div>
          <p className="nu-kicker">Shared KPIs · Reconciliation</p>
          <h2 className="nu-subhead" style={{ marginTop: '8px' }}>Canonical KPI Builder</h2>
          <p className="nu-body" style={{ color: 'var(--nu-grey)', maxWidth: '720px', marginTop: '8px' }}>
            Resolve divergent team definitions into a single source of truth. Every published
            definition writes to an auditable change trail across all dashboards.
          </p>
        </div>
        <div className="flex gap-4">
          {[
            { label: 'In Conflict', count: state.kpis.filter(k => k.conflict_state === 'In-Conflict').length, color: 'var(--nu-friction)' },
            { label: 'Reconciled', count: state.kpis.filter(k => k.conflict_state === 'Reconciled').length, color: 'var(--nu-success)' }
          ].map(s => (
            <div key={s.label} style={{ background: 'var(--nu-paper)', border: '1px solid var(--nu-hairline)', borderRadius: '8px', padding: '16px 24px', textAlign: 'center', minWidth: '120px' }}>
              <div className="nu-data" style={{ color: s.color }}>{s.count}</div>
              <div className="nu-label" style={{ marginTop: '8px' }}>{s.label}</div>
            </div>
          ))}
        </div>
      </div>

      {state.kpis.map(kpi => {
        const isConflict = kpi.conflict_state === 'In-Conflict';
        const isReviewing = reviewing === kpi.id;

        return (
          <NuCard key={kpi.id} style={{ padding: '0', overflow: 'hidden' }}>
            {/* KPI Header */}
            <div className="flex justify-between items-center" style={{ padding: '24px 30px', borderBottom: '1px solid var(--nu-hairline)' }}>
              <div className="flex items-center gap-4">
                <GitMerge size={22} color="var(--nu-ink)" />
                <div>
                  <h3 className="nu-subhead" style={{ fontSize: '24px' }}>{kpi.name}</h3>
                  <div className="flex items-center gap-4" style={{ marginTop: '6px' }}>
                    <span className="nu-label" style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <Users size={14} /> {kpi.owning_teams.join(' · ')}
                    </span>
                    <span className="nu-label" style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <Target size={14} /> {fmtValue(kpi)} of {fmtTarget(kpi)}
                    </span>
                  </div>
                </div>
              </div>
              {isConflict ? (
                <NuBadge variant="danger"><AlertOctagon size={13} /> In Conflict</NuBadge>
              ) : (
                <NuBadge variant="success"><CheckCircle2 size={13} /> Reconciled</NuBadge>
              )}
            </div>

            {/* p-compare: divergent prior definitions */}
            {isConflict && (
              <div style={{ padding: '28px 30px' }}>
                <p className="nu-label" style={{ marginBottom: '16px' }}>Divergent Definitions In Use</p>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr auto 1fr', alignItems: 'center', gap: '20px' }}>
                  {kpi.prior_definitions.map((def, i) => {
                    const [team, ...rest] = def.split(':');
                    return (
                      <React.Fragment key={i}>
                        <div style={{ background: 'var(--nu-ecru)', border: '1px solid var(--nu-hairline)', borderRadius: '8px', padding: '20px 22px', minHeight: '110px' }}>
                          <div className="nu-kicker" style={{ fontSize: '14px', letterSpacing: '2px' }}>{team.trim()}</div>
                          <div className="nu-body" style={{ fontSize: '18px', marginTop: '10px', color: 'var(--nu-ink)' }}>{rest.join(':').trim()}</div>
                        </div>
                        {i === 0 && (
                          <div style={{ width: '40px', height: '40px', borderRadius: '50%', background: '#FAEDED', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                            <span style={{ fontWeight: 700, color: 'var(--nu-friction)', fontSize: '18px' }}>≠</span>
                          </div>
                        )}
                      </React.Fragment>
                    );
                  })}
                </div>
              </div>
            )}

            {/* AI-proposed resolution */}
            <div style={{ padding: '28px 30px', background: isConflict ? '#FCFCFA' : 'var(--nu-paper)', borderTop: '1px solid var(--nu-hairline)' }}>
              <div className="flex items-center gap-4" style={{ marginBottom: '16px' }}>
                <Sparkles size={18} color="var(--nu-accent)" />
                <p className="nu-label" style={{ color: 'var(--nu-ink)', letterSpacing: '1.5px' }}>
                  {isConflict ? 'AI-Proposed Canonical Definition' : 'Published Canonical Definition'}
                </p>
              </div>

              <div style={{ background: 'var(--nu-paper)', border: '1px solid var(--nu-hairline)', borderRadius: '8px', padding: '24px' }}>
                <div className="nu-body" style={{ fontSize: '20px', color: 'var(--nu-ink)', fontWeight: 500 }}>
                  {kpi.canonical_definition}
                </div>
                <div style={{ marginTop: '18px', background: 'var(--nu-rail)', borderRadius: '6px', padding: '14px 18px' }}>
                  <div style={{ fontSize: '11px', letterSpacing: '2px', textTransform: 'uppercase', color: 'var(--nu-grey)', marginBottom: '8px' }}>Formula</div>
                  <code style={{ fontFamily: 'monospace', fontSize: '15px', color: '#E8E8E0' }}>{kpi.formula}</code>
                </div>
              </div>

              {/* p-hitl approval gate */}
              {isConflict && (
                <div style={{ marginTop: '20px', border: '1px solid var(--nu-hairline)', borderRadius: '8px', padding: '20px 24px', background: 'var(--nu-ecru)' }}>
                  {!isReviewing ? (
                    <div className="flex justify-between items-center">
                      <div className="flex items-center gap-4">
                        <div style={{ width: '32px', height: '32px', borderRadius: '50%', background: 'var(--nu-paper)', border: '1px solid var(--nu-hairline)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                          <window.lucide.ShieldCheck size={16} color="var(--nu-warning)" />
                        </div>
                        <div>
                          <div className="nu-body" style={{ fontSize: '16px', fontWeight: 500 }}>Human approval required</div>
                          <div className="nu-label" style={{ marginTop: '2px' }}>{state.user.name} · {state.user.role}</div>
                        </div>
                      </div>
                      <NuButton variant="secondary" onClick={() => setReviewing(kpi.id)}>Review Resolution</NuButton>
                    </div>
                  ) : (
                    <div className="flex-col gap-4">
                      <div className="flex items-center gap-4">
                        <window.lucide.AlertTriangle size={16} color="var(--nu-warning)" />
                        <span className="nu-body" style={{ fontSize: '16px' }}>
                          Publishing overwrites {kpi.prior_definitions.length} divergent definitions and pushes to all dashboards. This is logged to the change trail.
                        </span>
                      </div>
                      <div className="flex gap-4 items-center" style={{ justifyContent: 'flex-end' }}>
                        <NuButton variant="tertiary" onClick={() => setReviewing(null)}>Cancel</NuButton>
                        <NuButton
                          variant="primary"
                          onClick={() => { dispatch({ type: 'RESOLVE_KPI', payload: kpi.id }); setReviewing(null); }}
                        >
                          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
                            Accept &amp; Publish <ArrowRight size={14} />
                          </span>
                        </NuButton>
                      </div>
                    </div>
                  )}
                </div>
              )}

              {!isConflict && (
                <div className="flex items-center gap-4" style={{ marginTop: '18px', color: 'var(--nu-success)' }}>
                  <CheckCircle2 size={16} />
                  <span className="nu-label" style={{ color: 'var(--nu-success)' }}>
                    Published to all dashboards · owned by {kpi.owning_teams.join(' & ')}
                  </span>
                </div>
              )}
            </div>
          </NuCard>
        );
      })}
    </div>
  );
}

// PATTERN MANIFEST: p-portfolio-mix, p-rec
function Screen_roadmap_board({ state, dispatch }) {
  const { Lock, Sparkles, Target, Gauge, User, ArrowRight } = window.lucide;
  const [locked, setLocked] = React.useState(false);

  const phases = [
    { id: 'Phase 1: Foundations', label: 'Foundations', sub: 'Q1 2026 · Data plumbing & governance', tint: 'var(--nu-accent)' },
    { id: 'Phase 2: Intelligence', label: 'Intelligence', sub: 'Q2–Q3 2026 · Shared signals & scoring', tint: 'var(--nu-warning)' },
    { id: 'Phase 3: Scale', label: 'Scale', sub: 'Q4 2026 · Campaign-ready operations', tint: 'var(--nu-success)' }
  ];

  const velocityVariant = (v) => v === 'On track' ? 'success' : v === 'Not started' ? 'warning' : 'neutral';

  const ScoreBar = ({ value, color }) => (
    <div style={{ height: '6px', backgroundColor: 'var(--nu-ecru)', borderRadius: '999px', overflow: 'hidden', flex: 1 }}>
      <div style={{ width: `${value}%`, height: '100%', backgroundColor: color, borderRadius: '999px' }} />
    </div>
  );

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '32px' }}>
        <div>
          <p className="nu-kicker">2026 Readiness Plan</p>
          <h2 className="nu-subhead" style={{ marginTop: '8px' }}>Three-Pillar Roadmap Board</h2>
          <p className="nu-body" style={{ color: 'var(--nu-grey)', maxWidth: '640px', marginTop: '8px' }}>
            Sequence open recommendations into phased workstreams. Order is dependency-aware — foundational integration unlocks downstream intelligence.
          </p>
        </div>
        <NuButton variant={locked ? 'secondary' : 'primary'} onClick={() => setLocked(true)} disabled={locked}>
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '8px' }}>
            <Lock size={14} /> {locked ? 'Roadmap Locked' : 'Lock Roadmap'}
          </span>
        </NuButton>
      </div>

      {/* p-portfolio-mix board */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '24px', marginBottom: '40px' }}>
        {phases.map(phase => {
          const recs = state.recommendations.filter(r => r.phase === phase.id);
          return (
            <div key={phase.id} style={{ backgroundColor: 'var(--nu-ecru)', borderRadius: '8px', padding: '20px', minHeight: '420px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '4px' }}>
                <div style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: phase.tint }} />
                <span style={{ fontWeight: 700, fontSize: '16px', color: 'var(--nu-ink)' }}>{phase.label}</span>
                <span style={{ marginLeft: 'auto', fontSize: '12px', color: 'var(--nu-grey)', fontWeight: 600 }}>{recs.length}</span>
              </div>
              <p style={{ fontSize: '12px', color: 'var(--nu-grey)', margin: '0 0 18px 20px' }}>{phase.sub}</p>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
                {recs.length === 0 && (
                  <div style={{ border: '1.5px dashed var(--nu-hairline)', borderRadius: '8px', padding: '24px', textAlign: 'center', color: 'var(--nu-grey)', fontSize: '12.5px' }}>
                    No recommendations sequenced yet
                  </div>
                )}
                {recs.map(rec => {
                  const gap = state.gaps.find(g => g.id === rec.gap_id);
                  return (
                    <NuCard key={rec.id} style={{ padding: '18px 18px' }} onClick={() => gap && dispatch({ type: 'SELECT_GAP', payload: gap.id })}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                        <span style={{ fontFamily: 'monospace', fontSize: '11px', color: 'var(--nu-grey)' }}>{rec.id}</span>
                        <NuBadge variant={velocityVariant(rec.velocity)}>{rec.velocity}</NuBadge>
                      </div>
                      <p style={{ fontSize: '14px', fontWeight: 600, color: 'var(--nu-ink)', lineHeight: 1.35, margin: '0 0 14px' }}>{rec.title}</p>

                      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '14px' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          <Target size={13} color="var(--nu-success)" />
                          <span style={{ fontSize: '11px', color: 'var(--nu-grey)', width: '42px' }}>Impact</span>
                          <ScoreBar value={rec.impact_score} color="var(--nu-success)" />
                          <span style={{ fontSize: '12px', fontWeight: 700, fontVariantNumeric: 'tabular-nums', width: '24px', textAlign: 'right' }}>{rec.impact_score}</span>
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          <Gauge size={13} color="var(--nu-warning)" />
                          <span style={{ fontSize: '11px', color: 'var(--nu-grey)', width: '42px' }}>Effort</span>
                          <ScoreBar value={rec.effort_score} color="var(--nu-warning)" />
                          <span style={{ fontSize: '12px', fontWeight: 700, fontVariantNumeric: 'tabular-nums', width: '24px', textAlign: 'right' }}>{rec.effort_score}</span>
                        </div>
                      </div>

                      <div style={{ display: 'flex', alignItems: 'center', gap: '6px', paddingTop: '12px', borderTop: '1px solid var(--nu-hairline)' }}>
                        <User size={13} color="var(--nu-grey)" />
                        <span style={{ fontSize: '12px', color: 'var(--nu-ink)' }}>{rec.owner}</span>
                      </div>

                      {rec.status !== 'Accepted' && rec.status !== 'In-Progress' && (
                        <div style={{ marginTop: '12px' }}>
                          <NuButton variant="secondary" onClick={(e) => { e.stopPropagation(); dispatch({ type: 'ASSIGN_RECOMMENDATION', payload: { gapId: rec.gap_id, owner: rec.owner } }); }}>
                            Assign to owner
                          </NuButton>
                        </div>
                      )}
                    </NuCard>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>

      {/* AI sequencing rationale panel */}
      <NuCard style={{ backgroundColor: 'var(--nu-rail)', border: 'none' }}>
        <div style={{ display: 'flex', gap: '20px' }}>
          <div style={{ flexShrink: 0, width: '44px', height: '44px', borderRadius: '8px', backgroundColor: 'rgba(200,16,46,0.18)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Sparkles size={22} color="var(--nu-accent)" />
          </div>
          <div style={{ flex: 1 }}>
            <p className="nu-kicker" style={{ color: 'var(--nu-accent)' }}>AI Sequencing Rationale</p>
            <p style={{ color: 'var(--nu-paper)', fontSize: '15px', lineHeight: 1.6, margin: '10px 0 0', maxWidth: '900px' }}>
              <strong>REC-001</strong> (wealth-screen field mapping) is placed first in <strong>Foundations</strong> because it
              clears <strong>GAP-001</strong> — a $2.4M-at-risk integration break that blocks accurate capacity ratings.
              Every downstream Intelligence workstream depends on that field flowing cleanly between the AG and MG CRMs.
            </p>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginTop: '18px', flexWrap: 'wrap' }}>
              {['Map capacity field', 'Define $25k RACI', 'Reconcile engaged-alumnus KPI', 'Restore events sync'].map((step, i, arr) => (
                <div key={step} style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <span style={{ fontSize: '12.5px', color: 'rgba(255,255,255,0.85)', backgroundColor: 'rgba(255,255,255,0.08)', padding: '6px 12px', borderRadius: '999px' }}>{step}</span>
                  {i < arr.length - 1 && <ArrowRight size={15} color="var(--nu-grey)" />}
                </div>
              ))}
            </div>
            <p style={{ color: 'var(--nu-grey)', fontSize: '12.5px', margin: '18px 0 0' }}>
              Ordered by dependency depth, then descending impact / ascending effort. Locking publishes this sequence to all workstream leads.
            </p>
          </div>
        </div>
      </NuCard>
    </div>
  );
}

// PATTERN MANIFEST: p-kg (knowledge graph node/edge map), p-triage (detail triage panel)

function Screen_integration_map({ state, dispatch }) {
  const [selectedEdgeId, setSelectedEdgeId] = React.useState('E-EV-CRM');

  const C = {
    rail: '#0E1626', ink: '#16233C', accent: '#C8102E', paper: '#FFFFFF',
    ecru: '#F2F1EA', grey: '#73757A', hairline: '#DDDDD6', success: '#1D6E64', warning: '#A4804A'
  };

  // System nodes positioned on the canvas
  const nodes = [
    { id: 'CRM', label: 'Advancement CRM', sub: 'System of record', x: 470, y: 200, hub: true },
    { id: 'AG_CRM', label: 'Annual Giving CRM', sub: 'Solicitation engine', x: 120, y: 80 },
    { id: 'WEALTH', label: 'Wealth-Screen', sub: 'Capacity ratings', x: 120, y: 320 },
    { id: 'EVENTS', label: 'Events Platform', sub: 'Engagement signals', x: 820, y: 90 },
    { id: 'ALUMNI', label: 'Alumni Relations DB', sub: 'Engagement history', x: 820, y: 320 },
    { id: 'DW', label: 'Reporting Warehouse', sub: 'Dashboards & KPIs', x: 470, y: 430 }
  ];

  // Edges with health metadata
  const edges = [
    { id: 'E-AG-CRM', from: 'AG_CRM', to: 'CRM', status: 'degraded', last_success: '2025-10-06 04:12', error_rate: '7.4%', records_affected: 1840, gap_id: 'GAP-001', rec_id: 'REC-001', note: 'Wealth-screen capacity field silently dropped during AG→MG export.' },
    { id: 'E-WS-CRM', from: 'WEALTH', to: 'CRM', status: 'healthy', last_success: '2025-10-06 05:40', error_rate: '0.2%', records_affected: 0, gap_id: null, rec_id: null, note: 'Nightly capacity sync operating within SLA.' },
    { id: 'E-EV-CRM', from: 'EVENTS', to: 'CRM', status: 'broken', last_success: '2025-08-26 22:08', error_rate: '100%', records_affected: 8900, gap_id: 'GAP-004', rec_id: null, note: 'EventsPlatform→CRM sync down 41 days. No error alerting configured — engagement signals never reach CRM.' },
    { id: 'E-AL-CRM', from: 'ALUMNI', to: 'CRM', status: 'degraded', last_success: '2025-10-05 18:55', error_rate: '12.1%', records_affected: 5400, gap_id: 'GAP-003', rec_id: null, note: 'Conflicting engaged-alumnus definitions cause partial record rejection.' },
    { id: 'E-CRM-DW', from: 'CRM', to: 'DW', status: 'healthy', last_success: '2025-10-06 06:00', error_rate: '0.0%', records_affected: 0, gap_id: null, rec_id: null, note: 'Warehouse load completed cleanly.' }
  ];

  const nodeById = (id) => nodes.find(n => n.id === id);
  const selectedEdge = edges.find(e => e.id === selectedEdgeId) || null;

  const edgeColor = (s) => s === 'broken' ? C.accent : s === 'degraded' ? C.warning : C.success;
  const statusBadge = (s) => s === 'broken' ? 'danger' : s === 'degraded' ? 'warning' : 'success';
  const statusLabel = (s) => s === 'broken' ? 'Broken' : s === 'degraded' ? 'Degraded' : 'Healthy';

  const linkedGap = selectedEdge && selectedEdge.gap_id ? state.gaps.find(g => g.id === selectedEdge.gap_id) : null;
  const linkedRec = selectedEdge && selectedEdge.rec_id ? state.recommendations.find(r => r.id === selectedEdge.rec_id) : null;

  const Network = window.lucide.Network;
  const AlertTriangle = window.lucide.AlertTriangle;
  const Clock = window.lucide.Clock;
  const Activity = window.lucide.Activity;
  const Database = window.lucide.Database;
  const ArrowRight = window.lucide.ArrowRight;

  const counts = {
    broken: edges.filter(e => e.status === 'broken').length,
    degraded: edges.filter(e => e.status === 'degraded').length,
    healthy: edges.filter(e => e.status === 'healthy').length
  };

  return (
    <div>
      {/* Header band */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '28px' }}>
        <div>
          <p className="nu-kicker">Integration Health Map</p>
          <h2 className="nu-subhead" style={{ marginTop: '8px' }}>Where data debt accumulates</h2>
          <p className="nu-body" style={{ color: C.grey, maxWidth: '620px', marginTop: '8px' }}>
            Live state of every system-to-system link. Click a broken or degraded edge to triage.
          </p>
        </div>
        <div style={{ display: 'flex', gap: '12px' }}>
          {[['broken', counts.broken], ['degraded', counts.degraded], ['healthy', counts.healthy]].map(([k, v]) => (
            <NuCard key={k} style={{ padding: '16px 22px', minWidth: '108px' }}>
              <div className="nu-data" style={{ color: edgeColor(k) }}>{v}</div>
              <div className="nu-label" style={{ marginTop: '6px' }}>{statusLabel(k)}</div>
            </NuCard>
          ))}
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: selectedEdge ? '1fr 400px' : '1fr', gap: '24px', alignItems: 'start' }}>
        {/* ---- p-kg knowledge graph canvas ---- */}
        <NuCard style={{ padding: '0', overflow: 'hidden' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '18px 24px', borderBottom: `1px solid ${C.hairline}` }}>
            <Network size={18} color={C.accent} strokeWidth={2} />
            <span style={{ fontWeight: 700, fontSize: '15px', color: C.ink }}>System Topology</span>
            <span className="nu-label" style={{ marginLeft: 'auto' }}>6 systems · 5 links</span>
          </div>

          <div style={{ position: 'relative', backgroundColor: C.ecru }}>
            <svg viewBox="0 0 1000 520" style={{ width: '100%', display: 'block' }}>
              <defs>
                {edges.map(e => (
                  <marker key={'m' + e.id} id={'arrow-' + e.id} markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth">
                    <path d="M0,0 L8,3 L0,6 Z" fill={edgeColor(e.status)} />
                  </marker>
                ))}
              </defs>

              {/* Edges */}
              {edges.map(e => {
                const a = nodeById(e.from), b = nodeById(e.to);
                const isSel = e.id === selectedEdgeId;
                const clickable = e.status !== 'healthy';
                const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
                return (
                  <g key={e.id} style={{ cursor: clickable ? 'pointer' : 'default' }} onClick={() => clickable && setSelectedEdgeId(e.id)}>
                    <line
                      x1={a.x} y1={a.y} x2={b.x} y2={b.y}
                      stroke={edgeColor(e.status)}
                      strokeWidth={isSel ? 5 : 3}
                      strokeDasharray={e.status === 'broken' ? '10 7' : e.status === 'degraded' ? '2 6' : '0'}
                      markerEnd={`url(#arrow-${e.id})`}
                      opacity={isSel ? 1 : 0.85}
                    />
                    {/* invisible fat hit area */}
                    <line x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke="transparent" strokeWidth={20} />
                    {/* edge badge */}
                    {e.status !== 'healthy' && (
                      <g transform={`translate(${mx},${my})`}>
                        <circle r="13" fill={C.paper} stroke={edgeColor(e.status)} strokeWidth={isSel ? 3 : 2} />
                        <text textAnchor="middle" y="4" fontSize="13" fontWeight="700" fill={edgeColor(e.status)}>
                          {e.status === 'broken' ? '!' : '~'}
                        </text>
                      </g>
                    )}
                  </g>
                );
              })}

              {/* Nodes */}
              {nodes.map(n => (
                <g key={n.id} transform={`translate(${n.x},${n.y})`}>
                  <rect x={-78} y={-30} width={156} height={60} rx={10}
                    fill={n.hub ? C.rail : C.paper}
                    stroke={n.hub ? C.rail : C.hairline} strokeWidth={1.5} />
                  <text textAnchor="middle" y={-4} fontSize="14" fontWeight="700" fill={n.hub ? C.paper : C.ink}>{n.label}</text>
                  <text textAnchor="middle" y={15} fontSize="11" fill={n.hub ? '#9AA6BC' : C.grey}>{n.sub}</text>
                </g>
              ))}
            </svg>
          </div>

          {/* Legend */}
          <div style={{ display: 'flex', gap: '24px', padding: '16px 24px', borderTop: `1px solid ${C.hairline}` }}>
            {[['healthy', 'Healthy'], ['degraded', 'Degraded'], ['broken', 'Broken']].map(([k, l]) => (
              <div key={k} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span style={{ width: '22px', height: '3px', borderRadius: '2px', backgroundColor: edgeColor(k),
                  borderTop: k === 'broken' ? `3px dashed ${edgeColor(k)}` : 'none' }} />
                <span style={{ fontSize: '12px', color: C.grey, fontWeight: 500 }}>{l}</span>
              </div>
            ))}
          </div>
        </NuCard>

        {/* ---- p-triage detail panel ---- */}
        {selectedEdge && (
          <NuCard style={{ padding: '0', position: 'sticky', top: '24px' }}>
            <div style={{ padding: '20px 24px', borderBottom: `1px solid ${C.hairline}`, display: 'flex', alignItems: 'center', gap: '10px' }}>
              <AlertTriangle size={18} color={edgeColor(selectedEdge.status)} strokeWidth={2} />
              <span style={{ fontWeight: 700, fontSize: '15px', color: C.ink }}>Link Triage</span>
              <span style={{ marginLeft: 'auto' }}>
                <NuBadge variant={statusBadge(selectedEdge.status)}>{statusLabel(selectedEdge.status)}</NuBadge>
              </span>
            </div>

            <div style={{ padding: '24px' }}>
              {/* edge identity */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap', marginBottom: '16px' }}>
                <span style={{ fontWeight: 700, color: C.ink, fontSize: '14px' }}>{nodeById(selectedEdge.from).label}</span>
                <ArrowRight size={16} color={edgeColor(selectedEdge.status)} />
                <span style={{ fontWeight: 700, color: C.ink, fontSize: '14px' }}>{nodeById(selectedEdge.to).label}</span>
              </div>

              <p style={{ fontSize: '14px', lineHeight: 1.5, color: C.ink, margin: '0 0 20px 0' }}>{selectedEdge.note}</p>

              {/* triage stats */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0', border: `1px solid ${C.hairline}`, borderRadius: '8px', overflow: 'hidden' }}>
                {[
                  { icon: Clock, label: 'Last successful sync', val: selectedEdge.last_success },
                  { icon: Activity, label: 'Error rate', val: selectedEdge.error_rate, color: edgeColor(selectedEdge.status) },
                  { icon: Database, label: 'Records affected', val: selectedEdge.records_affected.toLocaleString() }
                ].map((row, i) => {
                  const Icon = row.icon;
                  return (
                    <div key={row.label} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '14px 16px', borderTop: i ? `1px solid ${C.hairline}` : 'none' }}>
                      <Icon size={16} color={C.grey} strokeWidth={2} />
                      <span style={{ fontSize: '13px', color: C.grey, flex: 1 }}>{row.label}</span>
                      <span style={{ fontWeight: 700, fontSize: '14px', color: row.color || C.ink, fontVariantNumeric: 'tabular-nums' }}>{row.val}</span>
                    </div>
                  );
                })}
              </div>

              {/* linked gap */}
              {linkedGap && (
                <div style={{ marginTop: '20px' }}>
                  <p className="nu-label" style={{ marginBottom: '10px' }}>Linked Gap</p>
                  <div
                    onClick={() => dispatch({ type: 'SELECT_GAP', payload: linkedGap.id })}
                    style={{ border: `1px solid ${C.hairline}`, borderRadius: '8px', padding: '14px 16px', cursor: 'pointer' }}
                    onMouseEnter={(e) => e.currentTarget.style.boxShadow = '0 4px 12px rgba(11,19,38,0.08)'}
                    onMouseLeave={(e) => e.currentTarget.style.boxShadow = 'none'}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
                      <span style={{ fontSize: '11px', fontWeight: 700, color: C.accent, letterSpacing: '0.5px' }}>{linkedGap.id}</span>
                      <NuBadge variant={linkedGap.status === 'In-Progress' ? 'warning' : linkedGap.status === 'Accepted' ? 'success' : 'neutral'}>{linkedGap.status}</NuBadge>
                    </div>
                    <p style={{ fontSize: '13px', fontWeight: 600, color: C.ink, margin: '8px 0 6px 0', lineHeight: 1.35 }}>{linkedGap.title}</p>
                    <p style={{ fontSize: '12px', color: C.grey, margin: 0 }}>
                      ${(linkedGap.dollar_at_risk / 1e6).toFixed(2)}M at risk · {linkedGap.affected_records.toLocaleString()} records
                    </p>
                  </div>
                </div>
              )}

              {/* linked recommendation */}
              {linkedRec && (
                <div style={{ marginTop: '16px' }}>
                  <p className="nu-label" style={{ marginBottom: '10px' }}>Active Recommendation</p>
                  <div style={{ border: `1px solid ${C.hairline}`, borderRadius: '8px', padding: '14px 16px' }}>
                    <p style={{ fontSize: '13px', fontWeight: 600, color: C.ink, margin: '0 0 8px 0', lineHeight: 1.35 }}>{linkedRec.title}</p>
                    <p style={{ fontSize: '12px', color: C.grey, margin: 0 }}>{linkedRec.owner} · {linkedRec.velocity}</p>
                  </div>
                </div>
              )}

              {/* actions */}
              <div style={{ display: 'flex', gap: '10px', marginTop: '24px' }}>
                {linkedGap && (
                  <NuButton variant="primary" onClick={() => dispatch({ type: 'SELECT_GAP', payload: linkedGap.id })}>
                    Open gap detail
                  </NuButton>
                )}
                {linkedGap && !linkedRec && (
                  <NuButton variant="secondary" onClick={() => dispatch({ type: 'ASSIGN_RECOMMENDATION', payload: { gapId: linkedGap.id, owner: 'Data Operations Manager' } })}>
                    Assign owner
                  </NuButton>
                )}
                {!linkedGap && (
                  <NuButton variant="secondary" onClick={() => dispatch({ type: 'NAVIGATE', payload: 'scorecard_home' })}>
                    Back to scorecard
                  </NuButton>
                )}
              </div>
            </div>
          </NuCard>
        )}
      </div>
    </div>
  );
}

// PATTERN MANIFEST: p-cohort (proto/Compare + proto/Stat), p-forecast-band (proto/Stat sparkline-derived), p-counterfactual (proto/Chips)
function Screen_benchmark_trajectory({ state, dispatch }) {
  const [scenario, setScenario] = React.useState('Baseline');
  const { metrics } = state;

  const peerMedian = { composite: 74, alignment: 70, integration: 66, kpi: 71 };

  const cohortRows = React.useMemo(() => ([
    { label: 'Composite Readiness', nu: metrics.composite_score, peer: peerMedian.composite },
    { label: 'Organizational Alignment', nu: metrics.alignment_score, peer: peerMedian.alignment },
    { label: 'Technology Integration', nu: metrics.integration_score, peer: peerMedian.integration },
    { label: 'Shared KPI Maturity', nu: metrics.kpi_score, peer: peerMedian.kpi }
  ]), [metrics]);

  // Friction curve points (monthly), higher = more friction
  const months = ['Oct 25','Dec','Feb','Apr','Jun','Aug','Oct','Dec 26','Feb 27'];
  const baseline = [62, 60, 58, 55, 52, 49, 46, 43, 41];
  const resolveP1 = [62, 56, 49, 41, 34, 28, 23, 19, 16];
  const curve = scenario === 'Baseline' ? baseline : resolveP1;
  const readinessThreshold = 30;

  // ETA: first index where curve crosses below threshold
  const etaIndex = curve.findIndex(v => v <= readinessThreshold);
  const etaLabel = etaIndex === -1 ? 'Beyond 2027 (est.)' : `${months[etaIndex]} (est.)`;
  const launchIndex = months.indexOf('Oct'); // 2026 launch marker

  const W = 760, H = 300, padL = 48, padR = 24, padT = 24, padB = 40;
  const plotW = W - padL - padR, plotH = H - padT - padB;
  const maxY = 70, minY = 0;
  const xAt = i => padL + (i / (months.length - 1)) * plotW;
  const yAt = v => padT + (1 - (v - minY) / (maxY - minY)) * plotH;

  const linePts = curve.map((v, i) => `${xAt(i)},${yAt(v)}`).join(' ');
  const bandTop = curve.map((v, i) => `${xAt(i)},${yAt(v + 6)}`);
  const bandBot = curve.map((v, i) => `${xAt(i)},${yAt(Math.max(0, v - 6))}`).reverse();
  const bandPath = `${bandTop.join(' ')} ${bandBot.join(' ')}`;

  const C = window.lucide;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '32px' }}>
      <div className="nu-kicker">Benchmark & Trajectory</div>

      {/* p-cohort */}
      <NuCard>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '8px' }}>
          <div>
            <h2 className="nu-subhead">Peer Cohort Position</h2>
            <p className="nu-body" style={{ color: 'var(--nu-grey)', maxWidth: '620px' }}>
              NU readiness vs. anonymized R1 private-research peer median (n=18 institutions). All figures est.
            </p>
          </div>
          <NuBadge variant="neutral">R1 Private · est.</NuBadge>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '18px', marginTop: '20px' }}>
          {/* Legend */}
          <div style={{ display: 'flex', gap: '24px', alignItems: 'center' }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12.5px', color: 'var(--nu-ink)' }}>
              <span style={{ width: '14px', height: '14px', borderRadius: '3px', background: 'var(--nu-accent)' }} /> Northeastern (est.)
            </span>
            <span style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12.5px', color: 'var(--nu-grey)' }}>
              <span style={{ width: '14px', height: '14px', borderRadius: '3px', background: 'var(--nu-grey)', opacity: 0.45 }} /> Peer median (est.)
            </span>
          </div>

          {cohortRows.map(row => {
            const delta = row.nu - row.peer;
            const ahead = delta >= 0;
            return (
              <div key={row.label} style={{ display: 'grid', gridTemplateColumns: '230px 1fr 120px', alignItems: 'center', gap: '16px' }}>
                <span style={{ fontSize: '13px', fontWeight: 500, color: 'var(--nu-ink)' }}>{row.label}</span>
                <div style={{ position: 'relative', height: '40px', display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: '5px' }}>
                  <div style={{ height: '14px', background: 'var(--nu-ecru)', borderRadius: '3px', position: 'relative' }}>
                    <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: `${row.nu}%`, background: 'var(--nu-accent)', borderRadius: '3px' }} />
                  </div>
                  <div style={{ height: '14px', background: 'var(--nu-ecru)', borderRadius: '3px', position: 'relative' }}>
                    <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: `${row.peer}%`, background: 'var(--nu-grey)', opacity: 0.45, borderRadius: '3px' }} />
                  </div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <span className="nu-data" style={{ fontSize: '22px', color: 'var(--nu-ink)' }}>{row.nu}</span>
                  <span style={{ fontSize: '12px', color: 'var(--nu-grey)', marginLeft: '4px' }}>est.</span>
                  <div style={{ fontSize: '11.5px', fontWeight: 600, color: ahead ? 'var(--nu-success)' : 'var(--nu-friction)' }}>
                    {ahead ? '▲' : '▼'} {Math.abs(delta)} vs peer
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </NuCard>

      {/* p-forecast-band + p-counterfactual */}
      <NuCard>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '20px', flexWrap: 'wrap', gap: '16px' }}>
          <div>
            <h2 className="nu-subhead">Friction Resolution Trajectory</h2>
            <p className="nu-body" style={{ color: 'var(--nu-grey)', maxWidth: '560px' }}>
              Projected composite friction index over time. Lower is better. Shaded band = est. confidence interval.
            </p>
          </div>

          {/* p-counterfactual chips */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', alignItems: 'flex-end' }}>
            <span className="nu-label" style={{ letterSpacing: '1.5px' }}>Scenario</span>
            <div style={{ display: 'flex', gap: '8px' }}>
              {['Baseline', 'Resolve P1'].map(s => {
                const sel = scenario === s;
                return (
                  <button
                    key={s}
                    onClick={() => setScenario(s)}
                    aria-pressed={sel}
                    style={{
                      padding: '7px 16px', borderRadius: '999px', cursor: 'pointer',
                      fontSize: '12.5px', fontWeight: 500,
                      background: sel ? 'var(--nu-paper)' : 'var(--nu-paper)',
                      border: sel ? '1.5px solid var(--nu-accent)' : '1px solid var(--nu-hairline)',
                      color: sel ? 'var(--nu-ink)' : 'var(--nu-grey)'
                    }}
                  >
                    {s}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <div style={{ display: 'flex', gap: '32px', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 600px', minWidth: '420px' }}>
            <svg viewBox={`0 0 ${W} ${H}`} style={{ width: '100%', height: 'auto' }} aria-hidden="true">
              {/* gridlines */}
              {[0, 20, 40, 60].map(g => (
                <g key={g}>
                  <line x1={padL} x2={W - padR} y1={yAt(g)} y2={yAt(g)} stroke="var(--nu-hairline)" strokeWidth="1" />
                  <text x={padL - 10} y={yAt(g) + 4} textAnchor="end" fontSize="10" fill="var(--nu-grey)">{g}</text>
                </g>
              ))}
              {/* readiness threshold */}
              <line x1={padL} x2={W - padR} y1={yAt(readinessThreshold)} y2={yAt(readinessThreshold)} stroke="var(--nu-success)" strokeWidth="1.5" strokeDasharray="5 4" />
              <text x={W - padR} y={yAt(readinessThreshold) - 6} textAnchor="end" fontSize="10" fontWeight="600" fill="var(--nu-success)">Launch-ready threshold (est.)</text>

              {/* 2026 launch marker */}
              <line x1={xAt(launchIndex)} x2={xAt(launchIndex)} y1={padT} y2={H - padB} stroke="var(--nu-ink)" strokeWidth="1.5" strokeDasharray="3 3" opacity="0.5" />
              <text x={xAt(launchIndex)} y={padT - 8} textAnchor="middle" fontSize="10" fontWeight="700" fill="var(--nu-ink)">2026 Launch</text>

              {/* confidence band */}
              <polygon points={bandPath} fill="var(--nu-accent)" opacity="0.12" />
              {/* curve */}
              <polyline points={linePts} fill="none" stroke="var(--nu-accent)" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
              {/* points */}
              {curve.map((v, i) => (
                <circle key={i} cx={xAt(i)} cy={yAt(v)} r="3" fill="var(--nu-paper)" stroke="var(--nu-accent)" strokeWidth="2" />
              ))}
              {/* x labels */}
              {months.map((m, i) => (
                <text key={m} x={xAt(i)} y={H - padB + 16} textAnchor="middle" fontSize="9.5" fill="var(--nu-grey)">{m}</text>
              ))}
            </svg>
          </div>

          {/* ETA stat */}
          <div style={{ flex: '0 0 260px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div style={{ background: 'var(--nu-ecru)', borderRadius: '8px', padding: '20px' }}>
              <div className="nu-label" style={{ letterSpacing: '1.5px' }}>Readiness ETA</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginTop: '10px' }}>
                <C.CalendarCheck size={22} color="var(--nu-success)" strokeWidth={1.5} />
                <span className="nu-data" style={{ fontSize: '28px', color: 'var(--nu-ink)' }}>{etaLabel}</span>
              </div>
              <p style={{ fontSize: '12px', color: 'var(--nu-grey)', marginTop: '8px', lineHeight: 1.4 }}>
                {scenario === 'Baseline'
                  ? 'At current velocity, friction crosses launch-ready late vs. the 2026 marker.'
                  : 'Resolving all Phase 1 foundations accelerates readiness ahead of the 2026 launch.'}
              </p>
            </div>

            <div style={{ background: 'var(--nu-paper)', border: '1px solid var(--nu-hairline)', borderRadius: '8px', padding: '20px' }}>
              <div className="nu-label" style={{ letterSpacing: '1.5px' }}>Friction at Launch</div>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: '6px', marginTop: '10px' }}>
                <span className="nu-data" style={{ fontSize: '32px', color: 'var(--nu-ink)' }}>{curve[launchIndex]}</span>
                <span style={{ fontSize: '13px', color: 'var(--nu-grey)' }}>idx · est.</span>
              </div>
              <div style={{ marginTop: '8px' }}>
                <NuBadge variant={curve[launchIndex] <= readinessThreshold ? 'success' : 'warning'}>
                  {curve[launchIndex] <= readinessThreshold ? 'Below threshold' : 'Above threshold'}
                </NuBadge>
              </div>
            </div>

            {scenario === 'Resolve P1' && (
              <NuButton variant="primary" onClick={() => dispatch({ type: 'NAVIGATE', payload: 'roadmap_board' })}>
                View Phase 1 roadmap
              </NuButton>
            )}
          </div>
        </div>
      </NuCard>
    </div>
  );
}

// PATTERN MANIFEST: p-doc-outline (proto/Tree+Chips), p-slide-draft (proto/Card+Timeline)
function Screen_cabinet_briefing({ state, dispatch }) {
  const L = window.lucide;
  const { metrics, gaps, recommendations, kpis } = state;

  const [sections, setSections] = React.useState({
    pillars: true,
    roadmap: true,
    benchmark: true
  });
  const [generating, setGenerating] = React.useState(false);
  const [exported, setExported] = React.useState(false);
  const [revealed, setRevealed] = React.useState(0);

  const topGaps = React.useMemo(() => [...gaps].sort((a, b) => b.severity - a.severity), [gaps]);

  const paragraphs = React.useMemo(() => {
    const out = [];
    out.push({
      key: 'exec',
      heading: 'Executive Summary',
      always: true,
      body: `Northeastern University Advancement enters the 2026 campaign with a composite readiness score of ${metrics.composite_score}/100. Across 28 detected alignment gaps, ${gaps.filter(g => g.status !== 'Proposed').length} have entered an active workstream. Total dollar-at-risk from unresolved integration and definition gaps is estimated at ${(gaps.reduce((s, g) => s + g.dollar_at_risk, 0) / 1e6).toFixed(1)}M, concentrated in the annual-giving to major-gifts handoff.`
    });
    if (sections.pillars) {
      out.push({
        key: 'pillars',
        heading: 'Readiness by Pillar',
        body: `Alignment scores ${metrics.alignment_score}, Integration ${metrics.integration_score}, and Shared KPIs ${metrics.kpi_score}. Integration remains the binding constraint: the highest-severity gap, "${topGaps[0].title}" (severity ${topGaps[0].severity}), places ${(topGaps[0].dollar_at_risk / 1e6).toFixed(1)}M at risk across ${topGaps[0].affected_records.toLocaleString()} records and is now In-Progress.`
      });
    }
    if (sections.roadmap) {
      out.push({
        key: 'roadmap',
        heading: 'Roadmap Commitments',
        body: `${recommendations.length} foundational recommendations are scheduled in Phase 1. "${recommendations[0].title}" (impact ${recommendations[0].impact_score}, effort ${recommendations[0].effort_score}) is owned by the ${recommendations[0].owner} and tracking ${recommendations[0].velocity.toLowerCase()}. We recommend the cabinet ratify the $25k transition RACI before the November governance review.`
      });
    }
    if (sections.benchmark) {
      out.push({
        key: 'benchmark',
        heading: 'Peer Benchmark',
        body: `At ${metrics.composite_score}/100, Northeastern sits in the second quartile of R1 private peers preparing comprehensive campaigns. Closing the two highest-severity integration gaps projects a composite lift to the high-70s within two quarters, moving the institution above the peer median ahead of the 2026 launch window.`
      });
    }
    return out;
  }, [sections, metrics, gaps, recommendations, topGaps]);

  React.useEffect(() => {
    setRevealed(0);
    setExported(false);
    const t = setInterval(() => {
      setRevealed(r => {
        if (r >= paragraphs.length) { clearInterval(t); return r; }
        return r + 1;
      });
    }, 320);
    return () => clearInterval(t);
  }, [paragraphs]);

  const outlineItems = [
    { id: 'pillars', label: 'Readiness by Pillar', sub: '3 pillar scores' },
    { id: 'roadmap', label: 'Roadmap Commitments', sub: `${recommendations.length} recommendations` },
    { id: 'benchmark', label: 'Peer Benchmark', sub: 'R1 private cohort' }
  ];

  const toggle = (id) => setSections(s => ({ ...s, [id]: !s[id] }));

  const handleExport = () => {
    if (generating) return;
    setGenerating(true);
    setExported(false);
    setTimeout(() => {
      setGenerating(false);
      setExported(true);
      dispatch({ type: 'NAVIGATE', payload: 'cabinet_briefing' });
    }, 2200);
  };

  return (
    <div>
      <style>{`
        @keyframes nuShimmer { 0% { background-position: -400px 0; } 100% { background-position: 400px 0; } }
        @keyframes nuFade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
        .nu-shimmer { background: linear-gradient(90deg, var(--nu-ecru) 25%, #E8E7DF 50%, var(--nu-ecru) 75%); background-size: 800px 100%; animation: nuShimmer 1.2s infinite linear; }
        .nu-para { animation: nuFade 0.4s ease both; }
      `}</style>

      <div className="nu-kicker" style={{ marginBottom: '8px' }}>Cabinet Briefing Export</div>
      <p className="nu-body" style={{ color: 'var(--nu-grey)', marginTop: 0, marginBottom: '32px', maxWidth: '720px' }}>
        Generate a board-grade readiness narrative and export a branded deck in under five minutes.
      </p>

      <div style={{ display: 'grid', gridTemplateColumns: '340px 1fr', gap: '32px', alignItems: 'start' }}>

        {/* p-doc-outline */}
        <div style={{ position: 'sticky', top: '24px' }}>
          <NuCard>
            <div className="nu-label" style={{ marginBottom: '16px' }}>DOCUMENT OUTLINE</div>

            {/* fixed exec section */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '11px 0', borderBottom: '1px solid var(--nu-hairline)' }}>
              <L.FileText size={16} strokeWidth={1.5} color="var(--nu-grey)" />
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: '13px', fontWeight: 600, color: 'var(--nu-ink)' }}>Executive Summary</div>
                <div style={{ fontSize: '11.5px', color: 'var(--nu-grey)' }}>Always included</div>
              </div>
              <L.Lock size={14} color="var(--nu-grey)" />
            </div>

            {outlineItems.map(item => {
              const on = sections[item.id];
              return (
                <div key={item.id}
                  onClick={() => toggle(item.id)}
                  style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '11px 0', borderBottom: '1px solid var(--nu-hairline)', cursor: 'pointer' }}>
                  <L.GripVertical size={16} strokeWidth={1.5} color="var(--nu-hairline)" />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: '13px', fontWeight: 600, color: on ? 'var(--nu-ink)' : 'var(--nu-grey)' }}>{item.label}</div>
                    <div style={{ fontSize: '11.5px', color: 'var(--nu-grey)' }}>{item.sub}</div>
                  </div>
                  <div style={{
                    width: '38px', height: '22px', borderRadius: '999px', flexShrink: 0,
                    backgroundColor: on ? 'var(--nu-accent)' : 'var(--nu-hairline)',
                    position: 'relative', transition: 'background-color 0.2s'
                  }}>
                    <div style={{
                      position: 'absolute', top: '2px', left: on ? '18px' : '2px',
                      width: '18px', height: '18px', borderRadius: '50%', backgroundColor: 'var(--nu-paper)',
                      transition: 'left 0.2s'
                    }} />
                  </div>
                </div>
              );
            })}

            <div style={{ marginTop: '24px' }}>
              <NuButton variant="primary" onClick={handleExport} disabled={generating}>
                {generating ? (
                  <span style={{ display: 'inline-flex', alignItems: 'center', gap: '8px' }}>
                    <L.Loader size={14} className="nu-spin" /> Generating…
                  </span>
                ) : (
                  <span style={{ display: 'inline-flex', alignItems: 'center', gap: '8px' }}>
                    <L.Download size={14} /> Export to PDF / Slides
                  </span>
                )}
              </NuButton>
            </div>
            {exported && (
              <div className="nu-para" style={{ marginTop: '14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <NuBadge variant="success"><L.CheckCircle size={12} /> Deck exported · 4 slides</NuBadge>
              </div>
            )}
          </NuCard>
        </div>

        {/* p-slide-draft live preview */}
        <NuCard style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ backgroundColor: 'var(--nu-rail)', padding: '20px 40px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
              <NuLogo />
              <div>
                <div style={{ color: 'var(--nu-paper)', fontWeight: 700, fontSize: '18px' }}>2026 Campaign Readiness Briefing</div>
                <div style={{ color: 'var(--nu-grey)', fontSize: '12px', letterSpacing: '1px' }}>PREPARED FOR THE ADVANCEMENT CABINET · OCT 2025</div>
              </div>
            </div>
            <NuBadge variant="warning">Draft · editable</NuBadge>
          </div>

          <div style={{ padding: '40px 48px', minHeight: '460px' }}>
            {generating && (
              <div style={{ marginBottom: '28px' }}>
                {[80, 95, 60].map((w, i) => (
                  <div key={i} className="nu-shimmer" style={{ height: '14px', width: w + '%', borderRadius: '4px', marginBottom: '10px' }} />
                ))}
              </div>
            )}

            {paragraphs.map((p, i) => {
              if (i >= revealed) return null;
              return (
                <div key={p.key} className="nu-para" style={{ marginBottom: '28px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '10px' }}>
                    <div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: 'var(--nu-accent)' }} />
                    <h3 className="nu-subhead" style={{ fontSize: '22px', margin: 0 }}>{p.heading}</h3>
                  </div>
                  <p
                    contentEditable
                    suppressContentEditableWarning
                    className="nu-body"
                    style={{ fontSize: '17px', margin: 0, color: 'var(--nu-ink)', outline: 'none', borderLeft: '2px solid transparent', paddingLeft: '18px', lineHeight: 1.6 }}
                    onFocus={(e) => e.currentTarget.style.borderLeft = '2px solid var(--nu-accent)'}
                    onBlur={(e) => e.currentTarget.style.borderLeft = '2px solid transparent'}
                  >
                    {p.body}
                  </p>
                </div>
              );
            })}

            {revealed < paragraphs.length && !generating && (
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--nu-grey)', fontSize: '13px' }}>
                <L.Sparkles size={14} /> AI drafting remaining sections…
              </div>
            )}
            {revealed >= paragraphs.length && !generating && (
              <div style={{ marginTop: '12px', paddingTop: '20px', borderTop: '1px dashed var(--nu-hairline)', color: 'var(--nu-grey)', fontSize: '12.5px' }}>
                {paragraphs.length} sections · {sections.pillars + sections.roadmap + sections.benchmark} optional included · Click any paragraph to edit before export.
              </div>
            )}
          </div>
        </NuCard>
      </div>

      <style>{`.nu-spin { animation: nuSpin 0.9s linear infinite; } @keyframes nuSpin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

function App() {
  const [state, dispatch] = React.useReducer(reducer, initialState);

  const renderScreen = () => {
    switch (state.activeScreen) {
      case 'scorecard_home': return <Screen_scorecard_home state={state} dispatch={dispatch} />;
      case 'gap_detail': return <Screen_gap_detail state={state} dispatch={dispatch} />;
      case 'kpi_builder': return <Screen_kpi_builder state={state} dispatch={dispatch} />;
      case 'roadmap_board': return <Screen_roadmap_board state={state} dispatch={dispatch} />;
      case 'integration_map': return <Screen_integration_map state={state} dispatch={dispatch} />;
      case 'benchmark_trajectory': return <Screen_benchmark_trajectory state={state} dispatch={dispatch} />;
      case 'cabinet_briefing': return <Screen_cabinet_briefing state={state} dispatch={dispatch} />;
      default: return <div>Screen not found</div>;
    }
  };

  return (
    <AppLayout state={state} dispatch={dispatch}>
      {renderScreen()}
    </AppLayout>
  );
}
